67: fn open_archive(zip_path: &str) -> Result<Archive> {
68:     let file = File::open(zip_path)
69:         .map_err(|e| zerr(format!("failed to open archive '{zip_path}': {e}")))?;
70:     ZipArchive::new(BufReader::with_capacity(64 * 1024, file))
71:         .map_err(|e| zerr(format!("failed to read archive '{zip_path}': {e}")))
72: }
