74: struct PendingFile {
75:     index: usize,
76:     out_path: PathBuf,
77:     mode: u32,
78:     mtime: Option<FileTime>,
79:     declared_size: u64,
80: }
81: 
82: struct PendingSymlink {
83:     out_path: PathBuf,
84:     target: String,
85: }
