87: fn run_extract(zip_path: &str, dest: &Path) -> Result<()> {
88:     let mut archive = open_archive(zip_path)?;
89: 
90:     fs::create_dir_all(dest).map_err(|e| {
91:         zerr(format!(
92:             "failed to create destination '{}': {e}",
93:             dest.display()
94:         ))
95:     })?;
96:     let dest_canon = dest
97:         .canonicalize()
98:         .map_err(|e| zerr(format!("failed to canonicalize destination: {e}")))?;
99: 
100:     // ── Pass 1 (serial): path checks + directory creation ────────────────────
101:     // Symlinks are NOT created here. Directories are created component-by-
102:     // component with `ensure_dir_nofollow`, which refuses to traverse a
103:     // symlink. So when pass 2 opens a queued file path, every intermediate
104:     // component is a real directory we created (or a pre-existing real
105:     // directory) — the archive cannot have re-pointed any of them.
106:     let mut dir_fixups: Vec<(PathBuf, u32, Option<FileTime>)> = Vec::new();
107:     let mut safe_dirs: HashSet<PathBuf> = HashSet::from([dest_canon.clone()]);
108:     let mut files: Vec<PendingFile> = Vec::with_capacity(archive.len());
109:     let mut symlinks: Vec<PendingSymlink> = Vec::new();
110: 
111:     for i in 0..archive.len() {
112:         let mut entry = archive
113:             .by_index(i)
114:             .map_err(|e| zerr(format!("failed to read entry {i}: {e}")))?;
115: 
116:         let mode = entry.unix_mode().map(|m| m & MODE_MASK);
117:         let mtime = entry.last_modified().map(dos_to_filetime);
118: 
119:         // `enclosed_name()` is the upstream Zip-Slip defence; we layer NUL +
120:         // Windows-reserved-name rejection on top.
121:         let Some(rel) = entry
122:             .enclosed_name()
123:             .filter(|p| extra_name_checks(p.as_path()))
124:         else {
125:             return Err(zerr(format!(
126:                 "refusing to extract '{}': path escapes destination",
127:                 entry.name()
128:             )));
129:         };
130:         let out_path = dest_canon.join(rel);
131: 
132:         if entry.is_dir() {
133:             ensure_dir_nofollow(&out_path, &dest_canon, &mut safe_dirs)?;
134:             dir_fixups.push((out_path, mode.unwrap_or(DEFAULT_DIR_MODE), mtime));
135:             continue;
136:         }
137: 
138:         if let Some(parent) = out_path.parent() {
139:             ensure_dir_nofollow(parent, &dest_canon, &mut safe_dirs)?;
140:         }
141: 
142:         if entry.is_symlink() {
143:             symlinks.push(PendingSymlink {
144:                 out_path,
145:                 target: read_symlink_target(&mut entry)?,
146:             });
147:             continue;
148:         }
149: 
150:         files.push(PendingFile {
151:             index: i,
152:             out_path,
153:             mode: mode.unwrap_or(DEFAULT_FILE_MODE),
154:             mtime,
155:             declared_size: entry.size(),
156:         });
157:     }
158: 
159:     // ── Pass 2 (parallel): regular files ─────────────────────────────────────
160:     let workers = thread::available_parallelism()
161:         .map_or(4, std::num::NonZero::get)
162:         .min(MAX_WORKERS)
163:         .min(files.len().max(1));
164: 
165:     if workers <= 1 {
166:         for f in &files {
167:             write_one(&mut archive, f)?;
168:         }
169:     } else {
170:         drop(archive);
171:         let next = AtomicUsize::new(0);
172:         let failed = AtomicBool::new(false);
173:         let first_err: Mutex<Option<Error>> = Mutex::new(None);
174:         thread::scope(|s| {
175:             for _ in 0..workers {
176:                 s.spawn(|| {
177:                     let mut arch = match open_archive(zip_path) {
178:                         Ok(a) => a,
179:                         Err(e) => return record_err(&failed, &first_err, e),
180:                     };
181:                     while !failed.load(Ordering::Relaxed) {
182:                         let i = next.fetch_add(1, Ordering::Relaxed);
183:                         if i >= files.len() {
184:                             break;
185:                         }
186:                         if let Err(e) = write_one(&mut arch, &files[i]) {
187:                             return record_err(&failed, &first_err, e);
188:                         }
189:                     }
190:                 });
191:             }
192:         });
193:         if let Some(e) = first_err.into_inner().unwrap() {
194:             return Err(e);
195:         }
196:     }
197: 
198:     // ── Pass 3 (serial): symlinks ────────────────────────────────────────────
199:     // All real dirs and files now exist; only now do we add symlinks. Each
200:     // target is resolved with a bounded walk that consults both the on-disk
201:     // tree *and* the full pending-symlink set, so an in-archive link chain
202:     // cannot smuggle the resolution outside `dest` regardless of entry order.
203:     //
204:     // Two entries whose link paths collide — byte-wise *or* under case-fold +
205:     // NFC (what APFS/NTFS will conflate) — would let `link_map` and the on-disk
206:     // state diverge mid-pass; refuse them.
207:     let mut link_map: HashMap<String, &str> = HashMap::with_capacity(symlinks.len());
208:     for s in &symlinks {
209:         if link_map
210:             .insert(fold_key(&s.out_path), s.target.as_str())
211:             .is_some()
212:         {
213:             return Err(zerr(format!(
214:                 "refusing archive with duplicate symlink entry '{}'",
215:                 s.out_path.display()
216:             )));
217:         }
218:     }
219:     for s in &symlinks {
220:         create_symlink(s, &dest_canon, &link_map)?;
221:     }
222: 
223:     // ── Pass 4 (serial): directory perms/mtimes, deepest first ───────────────
224:     // Paths recorded here are real directories created by `ensure_dir_nofollow`
225:     // and cannot have been replaced by a symlink (`remove_file` fails on dirs);
226:     // we lstat-guard anyway as defence in depth.
227:     dir_fixups.sort_by_key(|(p, _, _)| std::cmp::Reverse(p.as_os_str().len()));
228:     for (path, mode, mtime) in dir_fixups {
229:         if !fs::symlink_metadata(&path).is_ok_and(|m| m.is_dir()) {
230:             continue;
231:         }
232:         set_permissions(&path, mode);
233:         if let Some(t) = mtime {
234:             let _ = filetime::set_file_mtime(&path, t);
235:         }
236:     }
237: 
238:     Ok(())
239: }
