241: fn record_err(failed: &AtomicBool, slot: &Mutex<Option<Error>>, e: Error) {
242:     if !failed.swap(true, Ordering::Relaxed) {
243:         *slot.lock().unwrap() = Some(e);
244:     }
245: }
