314: /// Rejects what `enclosed_name()` doesn't: NUL bytes and Windows reserved
315: /// device names (so a Unix-authored zip containing `aux` can't bite on Windows).
316: fn extra_name_checks(p: &Path) -> bool {
317:     p.components().all(|c| match c {
318:         Component::Normal(s) => {
319:             let s = s.to_string_lossy();
320:             !s.contains('\0') && !is_reserved_windows_name(&s)
321:         }
322:         _ => true,
323:     })
324: }
325: 
326: fn is_reserved_windows_name(s: &str) -> bool {
327:     // Windows ignores trailing dots/spaces on path components, so `aux ` and
328:     // `aux.` both open the AUX device. Strip them before checking.
329:     let s = s.trim_end_matches([' ', '.']);
330:     let stem = s.split('.').next().unwrap_or(s);
331:     const RESERVED3: &[&str] = &["CON", "PRN", "AUX", "NUL"];
332:     if RESERVED3.iter().any(|r| stem.eq_ignore_ascii_case(r)) {
333:         return true;
334:     }
335:     // COM0–COM9 / LPT0–LPT9, plus the superscript ¹²³ variants Win11 added.
336:     let mut it = stem.chars();
337:     let head: [Option<char>; 3] = [it.next(), it.next(), it.next()];
338:     let prefix_ok = matches!(
339:         head.map(|c| c.map(|c| c.to_ascii_uppercase())),
340:         [Some('C'), Some('O'), Some('M')] | [Some('L'), Some('P'), Some('T')]
341:     );
342:     prefix_ok
343:         && matches!(
344:             (it.next(), it.next()),
345:             (Some('0'..='9' | '\u{B9}' | '\u{B2}' | '\u{B3}'), None)
346:         )
347: }
