451: fn read_symlink_target(entry: &mut impl Read) -> Result<String> {
452:     let mut limited = entry.take(MAX_SYMLINK_TARGET);
453:     let mut target = String::new();
454:     limited
455:         .read_to_string(&mut target)
456:         .map_err(|e| zerr(format!("failed to read symlink target: {e}")))?;
457:     // If the underlying reader still has bytes, the target was oversized.
458:     let mut probe = [0u8; 1];
