512: /// Walk `target` against the link's real parent, refusing to let the resolved
513: /// path leave `dest_canon` at any step. Intermediate symlinks — whether already
514: /// on disk or still pending in `link_map` — are followed in-place (so
515: /// `Versions/Current/Libraries` works when `Current → A`), with each hop
516: /// subject to the same rules: relative only, never ascend above `dest_canon`,
517: /// hop count capped. A symlink as the *final* component is left unresolved.
518: /// On success, returns the resolved path the link will point at.
519: fn verify_symlink_target(
520:     parent: &Path,
521:     target: &str,
522:     dest_canon: &Path,
523:     link_map: &HashMap<String, &str>,
524: ) -> std::result::Result<PathBuf, &'static str> {
525:     use std::ffi::OsString;
526:     const PARENT: &str = "..";
527: 
528:     let target = Path::new(target);
529:     if target.is_absolute() || target.as_os_str().is_empty() {
530:         return Err("target is absolute or empty");
531:     }
532:     // Stack of remaining components (reverse order so `pop` yields head-first).
533:     let mut work: Vec<OsString> = Vec::new();
534:     let push_rel = |work: &mut Vec<OsString>, p: &Path| {
535:         for c in p.components().rev() {
536:             match c {
537:                 Component::CurDir => {}
538:                 Component::ParentDir => work.push(PARENT.into()),
539:                 Component::Normal(n) => work.push(n.to_owned()),
540:                 Component::Prefix(_) | Component::RootDir => {
541:                     return Err("target is absolute or empty");
542:                 }
543:             }
544:         }
545:         Ok(())
546:     };
547:     push_rel(&mut work, target)?;
548: 
549:     let mut cur = parent.to_path_buf();
550:     let mut hops = 0u32;
551:     while let Some(seg) = work.pop() {
552:         if seg == PARENT {
553:             if cur == dest_canon {
554:                 return Err("target escapes destination");
555:             }
556:             cur.pop();
557:             continue;
558:         }
559:         cur.push(&seg);
560:         // Is `cur` a symlink — either pending from this archive, or on disk?
561:         // The map lookup is fold-keyed so a case/normalisation-mismatched
562:         // reference still finds the pending hop on APFS/NTFS.
563:         let hop: Option<PathBuf> = if let Some(t) = link_map.get(&fold_key(&cur)) {
564:             Some(PathBuf::from(t))
565:         } else {
566:             match fs::symlink_metadata(&cur) {
567:                 Ok(m) if m.file_type().is_symlink() => {
568:                     Some(fs::read_link(&cur).map_err(|_| "target is unreadable")?)
569:                 }
570:                 Ok(_) => None,
571:                 Err(e) if e.kind() == io::ErrorKind::NotFound => None,
572:                 Err(_) => return Err("target is unreadable"),
573:             }
574:         };
575:         if let Some(link) = hop {
576:             if work.is_empty() {
577:                 break; // final component; its own target is verified separately
578:             }
579:             hops += 1;
580:             if hops > MAX_SYMLINK_HOPS {
581:                 return Err("too many levels of symlinks in target");
582:             }
583:             cur.pop();
584:             push_rel(&mut work, &link)?;
585:         }
586:     }
587:     // The loop invariant keeps `cur` under `dest_canon`, but this is the
588:     // security boundary — keep the check unconditional so a future logic slip
589:     // in the hop resolver fails closed.
590:     if cur.starts_with(dest_canon) {
591:         Ok(cur)
592:     } else {
593:         Err("target escapes destination")
594:     }
595: }
