628: /// Whether the verified resolved target is a directory, following any
629: /// remaining symlink hops — pending links from this archive first (they may
630: /// not be on disk yet), then the on-disk tree via `fs::metadata`. A target
631: /// that resolves to nothing (dangling, loop, absolute hop) is treated as a
632: /// file: worst case is an untraversable link, same as a dangling one.
633: #[cfg(windows)]
634: fn resolved_target_is_dir(resolved: &Path, link_map: &HashMap<String, &str>) -> bool {
635:     let mut cur = resolved.to_path_buf();
636:     for _ in 0..MAX_SYMLINK_HOPS {
637:         let Some(t) = link_map.get(&fold_key(&cur)) else {
638:             return fs::metadata(&cur).is_ok_and(|m| m.is_dir());
639:         };
640:         let mut next = match cur.parent() {
641:             Some(p) => p.to_path_buf(),
642:             None => return false,
643:         };
644:         for c in Path::new(t).components() {
645:             match c {
646:                 Component::CurDir => {}
647:                 Component::ParentDir => {
648:                     next.pop();
649:                 }
650:                 Component::Normal(n) => next.push(n),
651:                 Component::Prefix(_) | Component::RootDir => return false,
652:             }
653:         }
654:         cur = next;
655:     }
656:     false
657: }
