672: /// DOS date/time → unix epoch seconds. DOS timestamps are local-time with no
673: /// zone; we treat them as UTC (same choice the original `extract-zip` makes).
674: fn dos_to_filetime(dt: zip::DateTime) -> FileTime {
675:     // Howard Hinnant's days_from_civil — exact for the proleptic Gregorian
676:     // calendar; DOS dates are 1980..=2107 so well inside the valid range.
677:     let (y, m, d) = (
678:         i64::from(dt.year()),
679:         i64::from(dt.month()),
680:         i64::from(dt.day()),
681:     );
682:     let y = y - i64::from(m <= 2);
683:     let era = y.div_euclid(400);
684:     let yoe = y - era * 400;
685:     let doy = (153 * (if m > 2 { m - 3 } else { m + 9 }) + 2) / 5 + d - 1;
686:     let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
687:     let days = era * 146_097 + doe - 719_468;
688:     let secs = days * 86_400
689:         + i64::from(dt.hour()) * 3_600
690:         + i64::from(dt.minute()) * 60
691:         + i64::from(dt.second());
692:     FileTime::from_unix_time(secs, 0)
693: }
