type Archive = ZipArchive<BufReader<File>>;

fn open_archive(zip_path: &str) -> Result<Archive> {
    let file = File::open(zip_path)
        .map_err(|e| zerr(format!("failed to open archive '{zip_path}': {e}")))?;
